var paths=new[]{"Assets/Prefabs/Player/SH10_Kael.prefab","Assets/Prefabs/Enemies/SH10_L01_Enemy.prefab","Assets/Prefabs/Bosses/SH10_L01_Boss.prefab"};return string.Join("\n",paths.Select(path=>{var asset=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path);var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);var a=asset?asset.GetComponentInChildren<UnityEngine.Animator>(true):null;var b=root?root.GetComponentInChildren<UnityEngine.Animator>(true):null;UnityEditor.PrefabUtility.UnloadPrefabContents(root);return path+" assetAnimator="+(a!=null)+" contentsAnimator="+(b!=null)+" childCount="+(asset?asset.GetComponentsInChildren<UnityEngine.Transform>(true).Length:0);}));
